8	 * See LICENSE in the root of the software repository for the full text of the License.
9	 */
10	
11	#include "engine/direct_client_handler.h"
12	#include "common/hixl_checker.h"
13	#include "common/hixl_log.h"
14	#include "common/hixl_utils.h"
15	#include "engine/client_handler_config_helper.h"
16	#include "engine/endpoint_generator/endpoint_generator.h"
17	
18	namespace hixl {
19	DirectClientHandler::DirectClientHandler(HixlClientHandle handle, const std::string &local_engine,
20	                                         const std::string &remote_engine, const HandlerCreateArgs::EndpointPair &pair)
21	    : handle_(handle), local_engine_(local_engine), remote_engine_(remote_engine), pair_(pair) {}
22	
23	Status DirectClientHandler::Create(const HandlerCreateArgs &args, std::unique_ptr<DirectClientHandler> &out) {
24	  const auto &pair = args.matched_pairs[0];
25	  EndpointDesc local_endpoint{};
26	  EndpointDesc remote_endpoint{};
27	  HIXL_CHK_STATUS_RET(EndpointGenerator::ConvertToEndpointDesc(pair.local, local_endpoint));
28	  HIXL_CHK_STATUS_RET(EndpointGenerator::ConvertToEndpointDesc(pair.remote, remote_endpoint));
29	  HixlClientDesc desc{};
30	  desc.server_ip = args.server_ip.c_str();
31	  desc.server_port = args.server_port;
32	  desc.local_endpoint = &local_endpoint;
33	  desc.remote_endpoint = &remote_endpoint;
34	  desc.tc = args.rdma_tc;
35	  desc.sl = args.rdma_sl;
36	  HixlClientHandle handle = nullptr;
37	  HixlClientConfig config{};
38	  const std::string global_resource_config = ClientHandlerConfigHelper::BuildGlobalResourceConfig(args);
39	  if (!global_resource_config.empty()) {
40	    config.global_resource_config = global_resource_config.c_str();
41	  }
42	  HIXL_CHK_STATUS_RET(HixlCSClientCreate(&desc, &config, &handle), "HixlCSClientCreate failed for type %s",
43	                      CommTypeToString(pair.type));
44	  out = MakeUnique<DirectClientHandler>(handle, args.local_engine, args.remote_engine, pair);
45	  HIXL_CHECK_NOTNULL(out, "DirectClientHandler create failed");
46	  return SUCCESS;
47	}
48	
49	Status DirectClientHandler::Connect(uint32_t timeout_ms) {
50	  std::lock_guard<std::mutex> lock(mutex_);
51	  if (is_connected_) {
52	    HIXL_LOGE(ALREADY_CONNECTED, "DirectClientHandler already connected");
53	    return ALREADY_CONNECTED;
54	  }
55	  Status ret = static_cast<Status>(HixlCSClientConnect(handle_, timeout_ms));
56	  if (ret == SUCCESS) {
57	    is_connected_ = true;
58	  } else {
59	    HIXL_LOGE(ret, "DirectClientHandler connect failed, ret: %d", ret);
60	  }
61	  return ret;
62	}
63	
64	Status DirectClientHandler::RegisterMem(const MemHandleInfo &mem_info) {
65	  CommMem hccl_mem{};
66	  hccl_mem.type = (mem_info.type == MemType::MEM_DEVICE) ? COMM_MEM_TYPE_DEVICE : COMM_MEM_TYPE_HOST;
67	  hccl_mem.addr = reinterpret_cast<void *>(mem_info.mem.addr);
68	  hccl_mem.size = mem_info.mem.len;
69	
70	  std::lock_guard<std::mutex> lock(mutex_);
71	  MemHandle mem_handle = nullptr;
72	  HIXL_CHK_STATUS_RET(HixlCSClientRegMem(handle_, nullptr, &hccl_mem, &mem_handle),
73	                      "DirectClientHandler register memory failed, addr: 0x%lx", mem_info.mem.addr);
74	  mem_handles_.push_back(mem_handle);
75	  return SUCCESS;
76	}
77	
78	Status DirectClientHandler::TransferAsync(const std::vector<TransferOpDesc> &op_descs, TransferOp operation,
79	                                          TransferReq &req) {
80	  uint32_t list_num = static_cast<uint32_t>(op_descs.size());
81	  std::vector<HixlOneSideOpDesc> hixl_descs(list_num);
82	  for (size_t i = 0; i < list_num; i++) {
83	    hixl_descs[i].remote_buf = reinterpret_cast<void *>(op_descs[i].remote_addr);
84	    hixl_descs[i].local_buf = reinterpret_cast<void *>(op_descs[i].local_addr);
85	    hixl_descs[i].len = op_descs[i].len;
86	  }
87	  CompleteHandle complete_handle = nullptr;
88	  {
89	    std::lock_guard<std::mutex> lock(mutex_);
90	    if (operation == WRITE) {
91	      HIXL_CHK_STATUS_RET(HixlCSClientBatchPutAsync(handle_, list_num, hixl_descs.data(), &complete_handle));
92	    } else {
93	      HIXL_CHK_STATUS_RET(HixlCSClientBatchGetAsync(handle_, list_num, hixl_descs.data(), &complete_handle));
94	    }
95	  }
96	  req = static_cast<TransferReq>(complete_handle);
97	  std::lock_guard<std::mutex> ch_lock(complete_handles_mutex_);
98	  complete_handles_[req] = complete_handle;
99	  return SUCCESS;
100	}
101	
102	Status DirectClientHandler::TransferSync(const std::vector<TransferOpDesc> &op_descs, TransferOp operation,
103	                                         uint32_t timeout_ms) {
104	  std::lock_guard<std::mutex> lock(mutex_);
105	  uint32_t list_num = static_cast<uint32_t>(op_descs.size());
106	  std::vector<HixlOneSideOpDesc> hixl_descs(list_num);
107	  for (size_t i = 0; i < list_num; i++) {
108	    hixl_descs[i].remote_buf = reinterpret_cast<void *>(op_descs[i].remote_addr);
109	    hixl_descs[i].local_buf = reinterpret_cast<void *>(op_descs[i].local_addr);
110	    hixl_descs[i].len = op_descs[i].len;
111	  }
112	  if (operation == WRITE) {
113	    return static_cast<Status>(HixlCSClientBatchPutSync(handle_, list_num, hixl_descs.data(), timeout_ms));
114	  }
115	  return static_cast<Status>(HixlCSClientBatchGetSync(handle_, list_num, hixl_descs.data(), timeout_ms));
116	}
117	
118	Status DirectClientHandler::GetTransferStatus(const TransferReq &req, TransferStatus &status) {
119	  std::scoped_lock lock(mutex_, complete_handles_mutex_);
120	  if (complete_handles_.empty()) {
121	    HIXL_LOGE(FAILED, "DirectClientHandler GetTransferStatus failed, no transfer tasks in progress, req:%p", req);
122	    status = TransferStatus::FAILED;
123	    return FAILED;
124	  }
125	  auto it = complete_handles_.find(req);
126	  if (it == complete_handles_.end()) {
127	    HIXL_LOGE(PARAM_INVALID, "DirectClientHandler GetTransferStatus failed, invalid req:%p", req);
128	    status = TransferStatus::FAILED;
129	    return PARAM_INVALID;
130	  }
131	  HixlCompleteStatus cs = HIXL_COMPLETE_STATUS_WAITING;
132	  Status ret = static_cast<Status>(HixlCSClientQueryCompleteStatus(handle_, it->second, &cs));
133	  if (ret != SUCCESS) {
134	    status = TransferStatus::FAILED;
135	    complete_handles_.erase(req);
136	    return ret;
137	  }
138	  status = ToTransferStatus(cs);
139	  if (status == TransferStatus::WAITING) {
140	    HIXL_LOGD("DirectClientHandler GetTransferStatus waiting, req:%p", req);
141	    return SUCCESS;
142	  }
143	  if (status == TransferStatus::COMPLETED) {
144	    HIXL_LOGI("DirectClientHandler GetTransferStatus completed, req:%p", req);
145	  } else {
146	    HIXL_LOGE(FAILED, "DirectClientHandler GetTransferStatus failed, cs=%d, req:%p", static_cast<int32_t>(cs), req);
147	  }
148	  complete_handles_.erase(req);
149	  return SUCCESS;
150	}
151	
152	Status DirectClientHandler::Finalize() {
153	  std::scoped_lock lock(mutex_, complete_handles_mutex_);
154	  complete_handles_.clear();
155	  for (auto &mh : mem_handles_) {
156	    if (mh != nullptr) {
157	      HixlCSClientUnregMem(handle_, mh);
158	    }
159	  }
160	  mem_handles_.clear();
161	  if (handle_ != nullptr) {
162	    HixlCSClientDestroy(handle_);
163	    handle_ = nullptr;
164	  }
165	  is_connected_ = false;
166	  return SUCCESS;
167	}
168	
169	void DirectClientHandler::Dump(const char *reason, DumpLogLevel level) const {
170	  std::scoped_lock lock(mutex_, complete_handles_mutex_);
171	  if (level == DumpLogLevel::ERROR) {
172	    HIXL_LOGE(FAILED,
173	              "[DirectClientHandler] dump, reason:%s, local_engine:%s, remote_engine:%s, handle:%p, "
174	              "is_connected:%d, mem_handle_count:%zu, complete_handle_count:%zu, comm_type:%s, "
175	              "local_endpoint:{%s}, remote_endpoint:{%s}",
176	              reason, local_engine_.c_str(), remote_engine_.c_str(), handle_, static_cast<int32_t>(is_connected_),
177	              mem_handles_.size(), complete_handles_.size(), CommTypeToString(pair_.type),
178	              pair_.local.ToString().c_str(), pair_.remote.ToString().c_str());
179	    return;
180	  }
181	  HIXL_EVENT(
182	      "[DirectClientHandler] dump, reason:%s, local_engine:%s, remote_engine:%s, handle:%p, "
183	      "is_connected:%d, mem_handle_count:%zu, complete_handle_count:%zu, comm_type:%s, "
184	      "local_endpoint:{%s}, remote_endpoint:{%s}",
185	      reason, local_engine_.c_str(), remote_engine_.c_str(), handle_, static_cast<int32_t>(is_connected_),
186	      mem_handles_.size(), complete_handles_.size(), CommTypeToString(pair_.type), pair_.local.ToString().c_str(),
187	      pair_.remote.ToString().c_str());
188	}
189	
190	}  // namespace hixl
191

