75	Status DeserializeMemInfoList(const std::string &json_str, std::vector<MemInfo> &mem_info_list) {
76	  nlohmann::json j;
77	  try {
78	    j = nlohmann::json::parse(json_str);
79	  } catch (const nlohmann::json::exception &e) {
80	    HIXL_LOGE(PARAM_INVALID, "Failed to parse mem info json, exception:%s", e.what());
81	    return PARAM_INVALID;
82	  }
83	  HIXL_CHK_BOOL_RET_STATUS(j.is_array(), PARAM_INVALID, "Invalid mem info json format, expect array");
84	
85	  mem_info_list.clear();
86	  for (const auto &item : j) {
87	    MemInfo info{};
88	    HIXL_CHK_STATUS_RET(ParseJsonField(item, "type", info.type), "Failed to parse mem type");
89	    HIXL_CHK_STATUS_RET(ParseJsonField(item, "addr", info.addr), "Failed to parse mem addr");
90	    HIXL_CHK_STATUS_RET(ParseJsonField(item, "size", info.size), "Failed to parse mem size");
91	    mem_info_list.push_back(info);
92	  }
93	  return SUCCESS;
94	}
