96	Status FetchRemoteMemInfo(int32_t sock, uint32_t timeout_ms, std::vector<MemInfo> &mem_info) {
97	  CtrlMsgHeader header{};
98	  header.magic = kMagicNumber;
99	  header.body_size = static_cast<uint64_t>(sizeof(CtrlMsgType));
100	  CtrlMsgType req_type = CtrlMsgType::kGetMemInfoReq;
101	  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(sock, &header, sizeof(header)),
102	                      "[UbClientHandler] Failed to send mem info header, fd:%d", sock);
103	  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(sock, &req_type, sizeof(req_type)),
104	                      "[UbClientHandler] Failed to send GetMemInfoReq, fd:%d", sock);
105	
106	  CtrlMsgHeader resp_header{};
107	  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Recv(sock, &resp_header, sizeof(resp_header), timeout_ms),
108	                      "[UbClientHandler] Failed to recv mem info header, fd:%d", sock);
109	  HIXL_CHK_BOOL_RET_STATUS(resp_header.magic == kMagicNumber, PARAM_INVALID,
110	                           "[UbClientHandler] Invalid magic in mem info resp, fd:%d: 0x%X", sock, resp_header.magic);
111	  HIXL_CHK_BOOL_RET_STATUS(
112	      resp_header.body_size > sizeof(CtrlMsgType) && resp_header.body_size <= kMaxRecvMemInfoBodySize, PARAM_INVALID,
113	      "[UbClientHandler] Invalid body_size=%" PRIu64 " in mem info resp, fd:%d", resp_header.body_size, sock);
114	
115	  std::vector<uint8_t> body(resp_header.body_size);
116	  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Recv(sock, body.data(), resp_header.body_size, timeout_ms),
117	                      "[UbClientHandler] Failed to recv mem info body, fd:%d", sock);
118	
119	  CtrlMsgType resp_type{};
120	  errno_t rc = memcpy_s(&resp_type, sizeof(resp_type), body.data(), sizeof(resp_type));
121	  HIXL_CHK_BOOL_RET_STATUS(rc == EOK, FAILED, "[UbClientHandler] memcpy_s failed, rc=%d", static_cast<int32_t>(rc));
122	  HIXL_CHK_BOOL_RET_STATUS(resp_type == CtrlMsgType::kGetMemInfoResp, PARAM_INVALID,
123	                           "[UbClientHandler] Unexpected msg_type=%d in mem info resp, expect=%d",
124	                           static_cast<int32_t>(resp_type), static_cast<int32_t>(CtrlMsgType::kGetMemInfoResp));
125	
126	  std::string json_str(reinterpret_cast<const char *>(body.data() + sizeof(resp_type)),
127	                       resp_header.body_size - sizeof(CtrlMsgType));
128	  return DeserializeMemInfoList(json_str, mem_info);
129	}
