131	Status ComputeRemainingMs(const std::chrono::steady_clock::time_point &start, uint32_t timeout_ms,
132	                          uint32_t &remaining_ms) {
133	  auto elapsed =
134	      std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - start).count();
135	  if (elapsed >= static_cast<int64_t>(timeout_ms)) {
136	    return TIMEOUT;
137	  }
138	  remaining_ms = static_cast<uint32_t>(static_cast<int64_t>(timeout_ms) - elapsed);
139	  return SUCCESS;
140	}
