152	Status UbClientHandler::Create(const HandlerCreateArgs &args, std::unique_ptr<UbClientHandler> &out) {
153	  std::map<CommType, HixlClientHandle> handles;
154	  std::map<CommType, HandlerCreateArgs::EndpointPair> link_pairs;
155	  const std::string global_resource_config = ClientHandlerConfigHelper::BuildGlobalResourceConfig(args);
156	  for (const auto &pair : args.matched_pairs) {
157	    EndpointDesc le{};
158	    EndpointDesc re{};
159	    HIXL_CHK_STATUS_RET(EndpointGenerator::ConvertToEndpointDesc(pair.local, le));
160	    HIXL_CHK_STATUS_RET(EndpointGenerator::ConvertToEndpointDesc(pair.remote, re));
161	    HixlClientDesc desc{};
162	    desc.server_ip = args.server_ip.c_str();
163	    desc.server_port = args.server_port;
164	    desc.local_endpoint = &le;
165	    desc.remote_endpoint = &re;
166	    desc.tc = args.rdma_tc;
167	    desc.sl = args.rdma_sl;
168	    HixlClientHandle handle = nullptr;
169	    HixlClientConfig config{};
170	    if (!global_resource_config.empty()) {
171	      config.global_resource_config = global_resource_config.c_str();
172	    }
173	    HIXL_CHK_STATUS_RET(HixlCSClientCreate(&desc, &config, &handle), "HixlCSClientCreate failed for type %s",
174	                        CommTypeToString(pair.type));
175	    handles[pair.type] = handle;
176	    link_pairs[pair.type] = pair;
177	  }
178	  out = MakeUnique<UbClientHandler>(std::move(handles), args.local_engine, args.remote_engine, std::move(link_pairs));
179	  HIXL_CHECK_NOTNULL(out, "UbClientHandler create failed");
180	
181	  // 若后续步骤失败，确保已创建的 handles 通过 Finalize 释放，避免资源泄漏
182	  HIXL_DISMISSABLE_GUARD(finalize_guard, [&out]() {
183	    if (out != nullptr) {
184	      (void)out->Finalize();
185	    }
186	  });
187	
188	  // 通过复用 ctrl_socket 向 server 获取对端内存信息，提前构建 remote_segments_
189	  out->lazy_mode_ = args.is_lazy;
190	  if (args.is_lazy) {
191	    out->connect_timeout_ms_ = args.timeout_ms;
192	  }
193	  std::vector<MemInfo> remote_mem_info;
194	  HIXL_CHK_STATUS_RET(FetchRemoteMemInfo(args.ctrl_socket, args.timeout_ms, remote_mem_info),
195	                      "Failed to fetch remote mem info");
196	  HIXL_CHK_STATUS_RET(out->BuildRemoteSegmentsFromMemInfo(remote_mem_info), "Failed to build remote segments");
197	  HIXL_DISMISS_GUARD(finalize_guard);
198	  return SUCCESS;
199	}
