201	Status UbClientHandler::Connect(uint32_t timeout_ms) {
202	  std::lock_guard<std::mutex> lock(handle_mutex_);
203	  if (handles_.empty()) {
204	    return FAILED;
205	  }
206	
207	  // 非 lazy 模式：直接连接全部链路
208	  if (!lazy_mode_) {
209	    HIXL_CHK_BOOL_RET_STATUS(connected_types_.empty(), ALREADY_CONNECTED,
210	                             "[UbClientHandler] All links already connected");
211	    return ConnectHandles(handles_, timeout_ms);
212	  }
213	
214	  // lazy 模式首次调用：仅保存超时，延迟到 transfer 时按需建链
215	  if (!connect_triggered_) {
216	    connect_triggered_ = true;
217	    HIXL_LOGI("[UbClientHandler] Auto-connect mode, deferring link connection to transfer time");
218	    return SUCCESS;
219	  }
220	
221	  HIXL_LOGE(ALREADY_CONNECTED, "[UbClientHandler] Auto-connect mode already triggered");
222	  return ALREADY_CONNECTED;
223	}
