225	Status UbClientHandler::EnsureLinksConnected(const std::vector<CommType> &types, uint32_t timeout_ms) {
226	  std::lock_guard<std::mutex> lock(handle_mutex_);
227	
228	  std::map<CommType, HixlClientHandle> pending;
229	  for (auto type : types) {
230	    if (connected_types_.count(type) != 0U) {
231	      continue;
232	    }
233	    auto it = handles_.find(type);
234	    HIXL_CHK_BOOL_RET_STATUS(it != handles_.end(), FAILED, "[UbClientHandler] No handle for type:%s",
235	                             CommTypeToString(type));
236	    pending.emplace(type, it->second);
237	  }
238	  if (pending.empty()) {
239	    return SUCCESS;
240	  }
241	  return ConnectHandles(pending, timeout_ms);
242	}
