244	Status UbClientHandler::ConnectHandles(const std::map<CommType, HixlClientHandle> &handles, uint32_t timeout_ms) {
245	  std::vector<std::future<Status>> futures;
246	  std::vector<CommType> type_order;  // 保持与 futures 索引对应，用于结果收集时回写 connected_types_
247	  OptionalAclrtContext context;
248	  HIXL_CHK_STATUS_RET(context.GetCurrentContext(), "GetCurrentContext failed");
249	
250	  ThreadPool thread_pool("ub_connect", handles.size());
251	  for (const auto &[type, handle] : handles) {
252	    type_order.push_back(type);
253	    futures.emplace_back(thread_pool.commit([handle, timeout_ms, type, &context]() -> Status {
254	      HIXL_CHK_STATUS_RET(context.SetCurrentContext(), "SetCurrentContext failed");
255	      HIXL_CHK_STATUS_RET(HixlCSClientConnect(handle, timeout_ms), "UbClientHandler Connect failed for type:%s",
256	                          CommTypeToString(type));
257	      HIXL_LOGI("[UbClientHandler] Connected type:%s successfully", CommTypeToString(type));
258	      return SUCCESS;
259	    }));
260	  }
261	  for (size_t i = 0; i < futures.size(); ++i) {
262	    HIXL_CHK_STATUS_RET(futures[i].get(), "[UbClientHandler] ConnectHandles failed for type:%s",
263	                        CommTypeToString(type_order[i]));
264	    connected_types_.insert(type_order[i]);
265	  }
266	
267	  return SUCCESS;
268	}
