270	Status UbClientHandler::BuildRemoteSegmentsFromMemInfo(const std::vector<MemInfo> &mem_info_list) {
271	  std::lock_guard<std::mutex> seg_lock(remote_seg_mutex_);
272	  remote_segments_.clear();
273	  SegmentPtr device_seg;
274	  SegmentPtr host_seg;
275	  for (const auto &info : mem_info_list) {
276	    auto &seg = (info.type == MEM_DEVICE) ? device_seg : host_seg;
277	    if (seg == nullptr) {
278	      seg = MakeShared<Segment>(info.type);
279	      HIXL_CHK_BOOL_RET_STATUS(seg != nullptr, FAILED, "Failed to create segment");
280	    }
281	    HIXL_CHK_STATUS_RET(seg->AddRange(info.addr, info.size), "AddRange failed");
282	  }
283	  if (device_seg != nullptr) {
284	    remote_segments_.push_back(device_seg);
285	  }
286	  if (host_seg != nullptr) {
287	    remote_segments_.push_back(host_seg);
288	  }
289	  HIXL_LOGI("[UbClientHandler] Built remote segments from %zu exchanged mem info entries", mem_info_list.size());
290	  return SUCCESS;
291	}
292	
293	Status UbClientHandler::RegisterMem(const MemHandleInfo &mem_info) {
294	  const auto &mem = mem_info.mem;
295	  const auto type = mem_info.type;
296	
297	  {
298	    std::lock_guard<std::mutex> lock(local_seg_mutex_);
299	    auto it = std::find_if(local_segments_.begin(), local_segments_.end(),
300	                           [type](const SegmentPtr &seg) { return seg->GetMemType() == type; });
301	    if (it != local_segments_.end()) {
302	      HIXL_CHK_STATUS_RET((*it)->AddRange(mem.addr, mem.len));
303	    } else {
304	      auto seg = MakeShared<Segment>(type);
305	      HIXL_CHK_BOOL_RET_STATUS(seg != nullptr, FAILED, "Failed to create segment");
306	      HIXL_CHK_STATUS_RET(seg->AddRange(mem.addr, mem.len));
307	      local_segments_.push_back(seg);
308	    }
309	  }
310	
311	  CommMem hccl_mem{};
312	  hccl_mem.type = (type == MemType::MEM_DEVICE) ? COMM_MEM_TYPE_DEVICE : COMM_MEM_TYPE_HOST;
313	  hccl_mem.addr = reinterpret_cast<void *>(mem.addr);
314	  hccl_mem.size = mem.len;
315	
316	  std::vector<CommType> comm_types;
317	  if (type == MemType::MEM_DEVICE) {
318	    comm_types = {CommType::COMM_TYPE_UB_D2H, CommType::COMM_TYPE_UB_D2D};
319	  } else {
320	    comm_types = {CommType::COMM_TYPE_UB_H2D, CommType::COMM_TYPE_UB_H2H};
321	  }
322	
323	  std::scoped_lock lock(handle_mutex_, mem_handle_mutex_);
324	  for (auto ct : comm_types) {
325	    auto h_it = handles_.find(ct);
326	    if (h_it == handles_.end()) {
327	      continue;
328	    }
329	    MemHandle mh = nullptr;
330	    HIXL_CHK_STATUS_RET(HixlCSClientRegMem(h_it->second, nullptr, &hccl_mem, &mh));
331	    mem_handles_[ct].push_back(mh);
332	  }
333	  return SUCCESS;
334	}
335	
336	Status UbClientHandler::TransferAsync(const std::vector<TransferOpDesc> &op_descs, TransferOp operation,
337	                                      TransferReq &req) {
338	  std::map<CommType, std::vector<TransferOpDesc>> table;
339	  HIXL_CHK_STATUS_RET(ClassifyTransfers(op_descs, table));
340	
341	  if (lazy_mode_) {
342	    std::vector<CommType> needed_types;
343	    for (const auto &pair : table) {
344	      needed_types.push_back(pair.first);
345	    }
346	    HIXL_CHK_STATUS_RET(EnsureLinksConnected(needed_types, connect_timeout_ms_));
347	  }
348	
349	  std::vector<BatchHandle> batch_handles;
350	  std::lock_guard<std::mutex> lock(handle_mutex_);
351	  for (const auto &[type, descs] : table) {
352	    auto it = handles_.find(type);
353	    if (it == handles_.end()) {
354	      return FAILED;
355	    }
356	    auto handle = it->second;
357	
358	    uint32_t list_num = static_cast<uint32_t>(descs.size());
359	    std::vector<HixlOneSideOpDesc> hixl_descs(list_num);
360	    for (size_t i = 0; i < list_num; i++) {
361	      hixl_descs[i].remote_buf = reinterpret_cast<void *>(descs[i].remote_addr);
362	      hixl_descs[i].local_buf = reinterpret_cast<void *>(descs[i].local_addr);
363	      hixl_descs[i].len = descs[i].len;
364	    }
365	    CompleteHandle complete_handle = nullptr;
366	    if (operation == WRITE) {
367	      HIXL_CHK_STATUS_RET(HixlCSClientBatchPutAsync(handle, list_num, hixl_descs.data(), &complete_handle));
368	    } else {
369	      HIXL_CHK_STATUS_RET(HixlCSClientBatchGetAsync(handle, list_num, hixl_descs.data(), &complete_handle));
370	    }
371	    batch_handles.push_back({type, complete_handle});
372	  }
373	  req = static_cast<TransferReq>(batch_handles[0].handle);
374	  std::lock_guard<std::mutex> ch_lock(complete_handles_mutex_);
375	  complete_handles_[req] = std::move(batch_handles);
376	  return SUCCESS;
377	}
378	
379	Status UbClientHandler::TransferSync(const std::vector<TransferOpDesc> &op_descs, TransferOp operation,
380	                                     uint32_t timeout_ms) {
381	  std::map<CommType, std::vector<TransferOpDesc>> table;
382	  HIXL_CHK_STATUS_RET(ClassifyTransfers(op_descs, table));
383	
384	  const auto sync_start = std::chrono::steady_clock::now();
385	
386	  if (lazy_mode_) {
387	    std::vector<CommType> needed_types;
388	    for (const auto &pair : table) {
389	      needed_types.push_back(pair.first);
390	    }
391	    uint32_t remaining_ms = 0;
392	    HIXL_CHK_STATUS_RET(ComputeRemainingMs(sync_start, timeout_ms, remaining_ms));
393	    HIXL_CHK_STATUS_RET(EnsureLinksConnected(needed_types, remaining_ms));
394	  }
395	
396	  for (const auto &[type, descs] : table) {
397	    uint32_t remaining_ms = 0;
398	    HIXL_CHK_STATUS_RET(ComputeRemainingMs(sync_start, timeout_ms, remaining_ms));
399	
400	    HixlClientHandle handle = nullptr;
401	    {
402	      std::lock_guard<std::mutex> lock(handle_mutex_);
403	      auto it = handles_.find(type);
404	      if (it == handles_.end()) {
405	        return FAILED;
406	      }
407	      handle = it->second;
408	    }
409	
410	    uint32_t list_num = static_cast<uint32_t>(descs.size());
411	    std::vector<HixlOneSideOpDesc> op_descs(list_num);
412	    for (size_t i = 0; i < list_num; i++) {
413	      op_descs[i].remote_buf = reinterpret_cast<void *>(descs[i].remote_addr);
414	      op_descs[i].local_buf = reinterpret_cast<void *>(descs[i].local_addr);
415	      op_descs[i].len = descs[i].len;
416	    }
417	    auto *cs = static_cast<HixlCSClient *>(handle);
418	    bool is_get = (operation != WRITE);
419	    HIXL_CHK_STATUS_RET(cs->BatchTransferSync(is_get, list_num, op_descs.data(), remaining_ms));
420	  }
421	  return SUCCESS;
422	}
423	
424	Status UbClientHandler::GetTransferStatus(const TransferReq &req, TransferStatus &status) {
425	  std::lock_guard<std::mutex> ch_lock(complete_handles_mutex_);
426	  if (complete_handles_.empty()) {
427	    HIXL_LOGE(FAILED, "UbClientHandler GetTransferStatus failed, no transfer tasks in progress, req:%p", req);
428	    status = TransferStatus::FAILED;
429	    return FAILED;
430	  }
431	  auto it = complete_handles_.find(req);
432	  if (it == complete_handles_.end()) {
433	    HIXL_LOGE(PARAM_INVALID, "UbClientHandler GetTransferStatus failed, invalid req");
434	    status = TransferStatus::FAILED;
435	    return PARAM_INVALID;
436	  }
437	
438	  bool all_complete = true;
439	  for (const auto &bh : it->second) {
440	    std::lock_guard<std::mutex> lock(handle_mutex_);
441	    auto h_it = handles_.find(bh.type);
442	    if (h_it == handles_.end()) {
443	      status = TransferStatus::FAILED;
444	      complete_handles_.erase(req);
445	      return FAILED;
446	    }
447	    HixlCompleteStatus cs = HIXL_COMPLETE_STATUS_WAITING;
448	    Status ret = static_cast<Status>(HixlCSClientQueryCompleteStatus(h_it->second, bh.handle, &cs));
449	    if (ret != SUCCESS) {
450	      status = TransferStatus::FAILED;
451	      complete_handles_.erase(req);
452	      return ret;
453	    }
454	    if (cs == HIXL_COMPLETE_STATUS_WAITING) {
455	      all_complete = false;
456	      continue;
457	    }
458	    if (cs != HIXL_COMPLETE_STATUS_COMPLETED) {
459	      status = ToTransferStatus(cs);
460	      HIXL_LOGE(FAILED, "UbClientHandler GetTransferStatus failed, cs=%d, req:%p", static_cast<int32_t>(cs), req);
461	      complete_handles_.erase(req);
462	      return SUCCESS;
463	    }
464	  }
465	
466	  status = all_complete ? TransferStatus::COMPLETED : TransferStatus::WAITING;
467	  if (all_complete) {
468	    HIXL_LOGI("UbClientHandler GetTransferStatus completed, req:%p", req);
469	    complete_handles_.erase(req);
470	  } else {
471	    HIXL_LOGI("UbClientHandler GetTransferStatus waiting, req:%p", req);
472	  }
473	  return SUCCESS;
474	}
475	
476	Status UbClientHandler::Finalize() {
477	  {
478	    std::lock_guard<std::mutex> lock(complete_handles_mutex_);
479	    complete_handles_.clear();
480	  }
481	  {
482	    std::scoped_lock lock(mem_handle_mutex_, handle_mutex_);
483	    for (auto &[type, mem_list] : mem_handles_) {
484	      auto it = handles_.find(type);
485	      if (it == handles_.end()) {
486	        continue;
487	      }
488	      for (auto &mh : mem_list) {
489	        if (mh != nullptr) {
490	          HixlCSClientUnregMem(it->second, mh);
491	        }
492	      }
493	    }
494	    mem_handles_.clear();
495	  }
496	  {
497	    std::lock_guard<std::mutex> lock(handle_mutex_);
498	    for (auto &pair : handles_) {
499	      if (pair.second != nullptr) {
500	        HixlCSClientDestroy(pair.second);
501	      }
502	    }
503	    handles_.clear();
504	    connected_types_.clear();
505	  }
506	  {
507	    std::lock_guard<std::mutex> lock(local_seg_mutex_);
508	    local_segments_.clear();
509	  }
510	  {
511	    std::lock_guard<std::mutex> lock(remote_seg_mutex_);
512	    remote_segments_.clear();
513	  }
514	  return SUCCESS;
515	}
516	
517	void UbClientHandler::Dump(const char *reason, DumpLogLevel level) const {
518	  struct DumpLink {
519	    CommType type;
520	    HixlClientHandle handle;
521	    bool connected;
522	    std::string local_endpoint;
523	    std::string remote_endpoint;
524	  };
525	  std::vector<DumpLink> links;
526	  size_t handle_count = 0;
527	  size_t connected_type_count = 0;
528	  size_t complete_req_count = 0;
529	  size_t local_segment_count = 0;
530	  size_t remote_segment_count = 0;
531	  {
532	    std::lock_guard<std::mutex> lock(handle_mutex_);
533	    handle_count = handles_.size();
534	    connected_type_count = connected_types_.size();
535	    for (const auto &[type, handle] : handles_) {
536	      auto pair_it = link_pairs_.find(type);
537	      links.push_back({type, handle, connected_types_.count(type) != 0U,
538	                       pair_it == link_pairs_.end() ? "" : pair_it->second.local.ToString(),
539	                       pair_it == link_pairs_.end() ? "" : pair_it->second.remote.ToString()});
540	    }
541	  }
542	  {
543	    std::lock_guard<std::mutex> lock(complete_handles_mutex_);
544	    complete_req_count = complete_handles_.size();
545	  }
546	  {
547	    std::lock_guard<std::mutex> lock(local_seg_mutex_);
548	    local_segment_count = local_segments_.size();
549	  }
550	  {
551	    std::lock_guard<std::mutex> lock(remote_seg_mutex_);
552	    remote_segment_count = remote_segments_.size();
553	  }
554	  LogUbDumpSummary(level, reason, local_engine_, remote_engine_, handle_count, connected_type_count, lazy_mode_,
555	                   complete_req_count, local_segment_count, remote_segment_count);
556	  for (const auto &link : links) {
557	    LogUbDumpLink(level, reason, local_engine_, remote_engine_, link.type, link.handle, link.connected,
558	                  link.local_endpoint, link.remote_endpoint);
559	  }
560	}
561	
562	Status UbClientHandler::ClassifyTransfers(const std::vector<TransferOpDesc> &op_descs,
563	                                          std::map<CommType, std::vector<TransferOpDesc>> &table) const {
564	  for (const auto &op : op_descs) {
565	    uint64_t local_end = 0U;
566	    uint64_t remote_end = 0U;
567	    HIXL_CHK_BOOL_RET_STATUS(!ge::AddOverflow(op.local_addr, op.len, local_end), PARAM_INVALID,
568	                             "Local memory range overflow: start:0x%lx, len:0x%lx", op.local_addr, op.len);
569	    HIXL_CHK_BOOL_RET_STATUS(!ge::AddOverflow(op.remote_addr, op.len, remote_end), PARAM_INVALID,
570	                             "Remote memory range overflow: start:0x%lx, len:0x%lx", op.remote_addr, op.len);
571	    MemType local_mem_type;
572	    {
573	      std::lock_guard<std::mutex> lock(local_seg_mutex_);
574	      HIXL_CHK_BOOL_RET_STATUS(
575	          GetMemType(local_segments_, op.local_addr, op.len, local_mem_type) == SUCCESS, PARAM_INVALID,
576	          "Local memory range is not registered before connection, start:0x%lx, end:0x%lx", op.local_addr, local_end);
577	    }
578	    MemType remote_mem_type;
579	    {
580	      std::lock_guard<std::mutex> lock(remote_seg_mutex_);
581	      HIXL_CHK_BOOL_RET_STATUS(GetMemType(remote_segments_, op.remote_addr, op.len, remote_mem_type) == SUCCESS,
582	                               PARAM_INVALID,
583	                               "Remote memory range is not registered before connection, start:0x%lx, end:0x%lx",
584	                               op.remote_addr, remote_end);
585	    }
586	    CommType ct = (local_mem_type == MEM_DEVICE)
587	                      ? ((remote_mem_type == MEM_DEVICE) ? CommType::COMM_TYPE_UB_D2D : CommType::COMM_TYPE_UB_D2H)
588	                      : ((remote_mem_type == MEM_DEVICE) ? CommType::COMM_TYPE_UB_H2D : CommType::COMM_TYPE_UB_H2H);
589	    table[ct].push_back(op);
590	  }
591	  return SUCCESS;
592	}
593	
594	Status UbClientHandler::GetMemType(const std::vector<SegmentPtr> &segments, uintptr_t addr, size_t len,
595	                                   MemType &mem_type) const {
596	  for (const auto &seg : segments) {
597	    if (seg->Contains(addr, addr + len)) {
598	      mem_type = seg->GetMemType();
599	      return SUCCESS;
600	    }
601	  }
602	  return PARAM_INVALID;
603	}
