106	                                        uint32_t timeout_ms) const {
107	  CtrlMsgHeader header{};
108	  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Recv(fd, &header, static_cast<uint32_t>(sizeof(header)), timeout_ms),
109	                      "HixlClient receive header failed, fd:%d", fd);
110	  HIXL_CHK_BOOL_RET_STATUS(header.magic == kMagicNumber, PARAM_INVALID,
111	                           "Invalid magic for HixlClient RecvEndpointInfoResp, expect:0x%X, actual:0x%X", kMagicNumber,
112	                           header.magic);
113	  HIXL_CHK_BOOL_RET_STATUS(
114	      header.body_size > sizeof(CtrlMsgType) && header.body_size <= kMaxRecvRespBodySize, PARAM_INVALID,
115	      "Invalid body_size in HixlClient RecvEndpointInfoResp, body_size=%" PRIu64 ", must be in (%zu, %" PRIu64 "]",
116	      header.body_size, sizeof(CtrlMsgType), kMaxRecvRespBodySize);
117	
118	  const uint64_t body_size = header.body_size;
119	  std::vector<uint8_t> body(body_size);
120	  HIXL_EVENT("[HixlClient] RecvEndpointInfoResp: receiving remote_endpoint_list body (%" PRIu64
121	             " bytes) from fd=%d begin",
122	             body_size, fd);
123	  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Recv(fd, body.data(), static_cast<uint32_t>(body_size), timeout_ms));
124	  HIXL_EVENT("[HixlClient] RecvEndpointInfoResp: receiving remote_endpoint_list body (%" PRIu64
125	             " bytes) from fd=%d success",
126	             body_size, fd);
127	
128	  CtrlMsgType msg_type{};
129	  const void *src = static_cast<const void *>(body.data());
130	  errno_t rc = memcpy_s(&msg_type, sizeof(msg_type), src, sizeof(msg_type));
131	  HIXL_CHK_BOOL_RET_STATUS(rc == EOK, FAILED, "memcpy_s msg_type failed, rc=%d", static_cast<int32_t>(rc));
132	  HIXL_CHK_BOOL_RET_STATUS(msg_type == CtrlMsgType::kGetEndpointInfoResp, PARAM_INVALID,
133	                           "Unexpected msg_type=%d in RecvEndpointInfoResp, expect=%d", static_cast<int32_t>(msg_type),
134	                           static_cast<int32_t>(CtrlMsgType::kGetEndpointInfoResp));
135	
136	  const size_t json_len = static_cast<size_t>(body_size - sizeof(CtrlMsgType));
137	  std::string json_str(reinterpret_cast<const char *>(body.data() + sizeof(msg_type)), json_len);
138	  return EndpointGenerator::DeserializeEndpointConfigList(json_str, remote_endpoint_list);
139	}
