276	  Status ret = (client_handler_ != nullptr) ? client_handler_->Finalize() : SUCCESS;
277	  if (ret == SUCCESS) {
278	    HIXL_DISMISS_GUARD(dump_guard);
279	    HIXL_EVENT("[HixlClient] disconnect link success, local_engine:%s, remote_engine:%s", local_engine_.c_str(),
280	               remote_engine_.c_str());
