298	Status HixlClient::RecvNotifyAck(int32_t fd, int32_t timeout_ms) const {
299	  CtrlMsgHeader header{};
300	  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Recv(fd, &header, static_cast<uint32_t>(sizeof(header)), timeout_ms),
301	                      "HixlClient receive NotifyAck header failed, fd:%d", fd);
302	  HIXL_CHK_BOOL_RET_STATUS(header.magic == kMagicNumber, PARAM_INVALID,
303	                           "Invalid magic for NotifyAck, expect:0x%X, actual:0x%X", kMagicNumber, header.magic);
304	  HIXL_CHK_BOOL_RET_STATUS(header.body_size > sizeof(CtrlMsgType) && header.body_size <= kMaxRecvRespBodySize,
305	                           PARAM_INVALID, "Invalid body_size for NotifyAck, body_size:%lu", header.body_size);
306	
307	  const uint64_t body_size = header.body_size;
308	  std::vector<uint8_t> body(body_size);
309	  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Recv(fd, body.data(), static_cast<uint32_t>(body_size), timeout_ms),
310	                      "HixlClient receive NotifyAck body failed, fd:%d", fd);
311	
312	  CtrlMsgType msg_type{};
313	  const void *src = static_cast<const void *>(body.data());
314	  errno_t rc = memcpy_s(&msg_type, sizeof(msg_type), src, sizeof(msg_type));
315	  HIXL_CHK_BOOL_RET_STATUS(rc == EOK, FAILED, "memcpy_s msg_type failed, rc:%d", static_cast<int32_t>(rc));
316	  HIXL_CHK_BOOL_RET_STATUS(msg_type == CtrlMsgType::kNotifyAck, PARAM_INVALID,
317	                           "Unexpected msg_type=%d, expect kNotifyAck=%d", static_cast<int32_t>(msg_type),
318	                           static_cast<int32_t>(CtrlMsgType::kNotifyAck));
319	
320	  const size_t json_len = static_cast<size_t>(body_size - sizeof(CtrlMsgType));
321	  std::string json_str(reinterpret_cast<const char *>(body.data() + sizeof(msg_type)), json_len);
322	  Status result = SUCCESS;
323	  try {
324	    result = ParseNotifyAckResult(json_str);
325	  } catch (const nlohmann::json::exception &e) {
326	    HIXL_LOGE(PARAM_INVALID, "Failed to parse NotifyAck, exception:%s", e.what());
327	    return PARAM_INVALID;
328	  }
329	  if (result != SUCCESS) {
330	    HIXL_LOGE(result, "NotifyAck result failed, result:%u", result);
331	    return result;
332	  }
333	  HIXL_LOGI("HixlClient received NotifyAck success");
334	  return SUCCESS;
335	}
336	
337	Status HixlClient::CheckAlive() {
338	  std::lock_guard<std::mutex> lock(mutex_);
339	  HIXL_CHK_BOOL_RET_STATUS(ctrl_socket_ >= 0, FAILED,
340	                           "HixlClient CheckAlive failed, peer_ip:%s, peer_port:%u, ctrl socket is invalid, fd:%d",
341	                           server_ip_.c_str(), server_port_, ctrl_socket_);
342	  CtrlMsgHeader header{};
343	  header.magic = kMagicNumber;
344	  header.body_size = sizeof(CtrlMsgType);
345	  CtrlMsgType msg_type = CtrlMsgType::kHeartBeat;
346	  std::array<uint8_t, sizeof(CtrlMsgHeader) + sizeof(CtrlMsgType)> heartbeat_msg{};
347	  errno_t rc = memcpy_s(heartbeat_msg.data(), heartbeat_msg.size(), &header, sizeof(header));
348	  HIXL_CHK_BOOL_RET_STATUS(rc == EOK, FAILED, "memcpy_s heartbeat header failed, rc=%d", static_cast<int32_t>(rc));
349	  rc = memcpy_s(heartbeat_msg.data() + sizeof(header), heartbeat_msg.size() - sizeof(header), &msg_type,
350	                sizeof(msg_type));
351	  HIXL_CHK_BOOL_RET_STATUS(rc == EOK, FAILED, "memcpy_s heartbeat msg_type failed, rc=%d", static_cast<int32_t>(rc));
352	
353	  int32_t err_no = 0;
354	  Status ret = CtrlMsgPlugin::Send(ctrl_socket_, heartbeat_msg.data(), heartbeat_msg.size(), err_no);
355	  if (ret != SUCCESS) {
356	    if (IsSocketDisconnectedErrno(err_no)) {
357	      HIXL_LOGE(FAILED, "HixlClient CheckAlive send heartbeat failed, peer_ip:%s, peer_port:%u, fd=%d, errno=%d",
358	                server_ip_.c_str(), server_port_, ctrl_socket_, err_no);
359	      CloseCtrlSocket();
360	      return FAILED;
361	    }
362	    HIXL_LOGW("HixlClient CheckAlive send heartbeat failed, peer_ip:%s, peer_port:%u, fd=%d, errno=%d",
363	              server_ip_.c_str(), server_port_, ctrl_socket_, err_no);
364	    return SUCCESS;
365	  }
366	  return SUCCESS;
367	}
368	
369	Status HixlClient::SendNotify(const NotifyDesc &notify, int32_t timeout_ms) const {
370	  std::lock_guard<std::mutex> lock(mutex_);
371	  NotifyMsg notify_msg{notify.name.GetString(), notify.notify_msg.GetString()};
372	
373	  HIXL_CHK_BOOL_RET_STATUS(notify_msg.name.size() <= kMaxNotifyNameLen, PARAM_INVALID,
374	                           "Notify name length invalid, size:%zu, max:%zu", notify_msg.name.size(), kMaxNotifyNameLen);
375	  HIXL_CHK_BOOL_RET_STATUS(notify_msg.notify_msg.size() <= kMaxNotifyMsgLen, PARAM_INVALID,
376	                           "Notify message too long, size:%zu, max:%zu", notify_msg.notify_msg.size(),
377	                           kMaxNotifyMsgLen);
378	
379	  std::string msg_str;
380	  try {
381	    msg_str = SerializeNotifyMsg(notify_msg);
382	  } catch (const nlohmann::json::exception &e) {
383	    HIXL_LOGE(PARAM_INVALID, "Failed to serialize NotifyMsg, exception:%s", e.what());
384	    return PARAM_INVALID;
385	  }
386	
387	  CtrlMsgHeader header{};
388	  header.magic = kMagicNumber;
389	  header.body_size = static_cast<uint64_t>(sizeof(CtrlMsgType) + msg_str.size());
390	  CtrlMsgType msg_type = CtrlMsgType::kNotify;
391	
392	  HIXL_CHK_BOOL_RET_STATUS(ctrl_socket_ >= 0, FAILED, "HixlClient SendNotify failed, ctrl socket is invalid, fd:%d",
393	                           ctrl_socket_);
394	
395	  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(ctrl_socket_, &header, static_cast<uint64_t>(sizeof(header))),
396	                      "HixlClient send NotifyMsg header failed, socket:%d", ctrl_socket_);
397	  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(ctrl_socket_, &msg_type, static_cast<uint64_t>(sizeof(msg_type))),
398	                      "HixlClient send NotifyMsg msg_type failed, socket:%d", ctrl_socket_);
399	  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(ctrl_socket_, msg_str.c_str(), static_cast<uint64_t>(msg_str.size())),
400	                      "HixlClient send NotifyMsg body failed, socket:%d", ctrl_socket_);
401	
402	  HIXL_LOGI("HixlClient sent NotifyMsg, name:%s, socket:%d", notify_msg.name.c_str(), ctrl_socket_);
403	  HIXL_CHK_STATUS_RET(RecvNotifyAck(ctrl_socket_, timeout_ms),
404	                      "HixlClient receive NotifyAck failed, timeout:%d ms, socket:%d", timeout_ms, ctrl_socket_);
405	  return SUCCESS;
406	}
407	}  // namespace hixl
